def parse_iso8601(datestring):
    m = ISO8601_REGEX.match(datestring)
    if not m:
        raise ValueError('unable to parse date string %r' % datestring)
    groups = m.groupdict()
    tz = groups['timezone']
    if tz == 'Z':
      tz = FixedOffset(0)
    elif tz:
        m = TIMEZONE_REGEX.match(tz)
        prefix, hours, minutes = m.groups()
        hours, minutes = int(hours), int(minutes)
        if prefix == '-':
            hours = -hours
            minutes = -minutes
        tz = FixedOffset(minutes + hours * 60)
    frac = groups['fraction']
    groups['fraction'] = int(float('0.%s' % frac) * 1e6) if frac else 0
    return datetime(
        int(groups['year']), int(groups['month']), int(groups['day']),
        int(groups['hour']), int(groups['minute']), int(groups['second']),
        int(groups['fraction']), tz
    )

def execute_from_commandline(self, argv=None):
    if argv is None:
        argv = list(sys.argv)
    # Should we load any special concurrency environment?
    self.maybe_patch_concurrency(argv)
    self.on_concurrency_setup()

    # Dump version and exit if '--version' arg set.
    self.early_version(argv)
    try:
        argv = self.setup_app_from_commandline(argv)
    except ModuleNotFoundError as e:
        self.on_error(UNABLE_TO_LOAD_APP_MODULE_NOT_FOUND.format(e.name))
        return EX_FAILURE
    except AttributeError as e:
        msg = e.args[0].capitalize()
        self.on_error(UNABLE_TO_LOAD_APP_APP_MISSING.format(msg))
        return EX_FAILURE

    self.prog_name = os.path.basename(argv[0])
    return self.handle_argv(self.prog_name, argv[1:])

