          task_id=None, retries=None, throw=None,
          logfile=None, loglevel=None, headers=None, **options):
    # trace imports Task, so need to import inline.
    from celery.app.trace import build_tracer

    app = self._get_app()
    args = args or ()
    kwargs = kwargs or {}
